//! Purpose:
//! Replay tables for the parser corpus: every `run()` / `dump_events()` call of the PHP
//! probe scripts, in order, with the section headers they printed. The matching expected
//! outputs (`fixtures/<name>.out`, recorded with PHP 8.5.10 / libxml2 2.15.3) are
//! reproduced from these tables by the generated scripts `fixtures/<name>.php`.
//!
//! Called from:
//! - `crate::parser::tests::probes` (replays the tables through the bridge);
//! - `crate::parser::tests::regen` (emits the PHP scripts that re-record the fixtures).
//!
//! Key details:
//! - Documents are byte strings exactly as PHP received them (hex-recorded).
//! - `handlers` is the probe's handler list spelling, reused verbatim in summary lines.
//! - To re-verify or re-record a fixture: `cargo test -p elephc-xml --lib -- regen --ignored`
//!   rewrites the scripts (and, when `php` is on `PATH`, checks each one reproduces its
//!   `.out` byte for byte); then `php fixtures/<name>.php > fixtures/<name>.out`
//!   re-records it. The tables are the single source of truth: edit them, regenerate, and
//!   commit the scripts alongside.

/// One replay step.
pub(crate) enum Entry {
    /// A `== section` header echoed by the script.
    Section(&'static str),
    /// One parse call.
    Case {
        doc: &'static [u8],
        handlers: &'static str,
        ns: bool,
        /// probe1 only: `XML_OPTION_CASE_FOLDING` turned off.
        case_folding_off: bool,
    },
}

